ruleContent.content:
@js:
(function(){
  var TBL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

  // 纯 JS base64 解码：解码结果是 %xx 形式的 ASCII，String.fromCharCode 足够
  function b64(s){
    s = String(s).replace(/[^A-Za-z0-9+/]/g, '');
    var out = '', i = 0, a, b, c, dd, e;
    while (i + 1 < s.length){
      a = TBL.indexOf(s.charAt(i++));
      b = TBL.indexOf(s.charAt(i++));
      c  = i < s.length ? TBL.indexOf(s.charAt(i++)) : -1;
      dd = i < s.length ? TBL.indexOf(s.charAt(i++)) : -1;
      e = (a << 18) | (b << 12) | ((c < 0 ? 0 : c) << 6) | (dd < 0 ? 0 : dd);
      out += String.fromCharCode((e >>> 16) & 255);
      if (c  >= 0) out += String.fromCharCode((e >>> 8) & 255);
      if (dd >= 0) out += String.fromCharCode(e & 255);
    }
    return out;
  }

  var h = '';
  try { h = String(result || ''); } catch(err) { return ''; }

  // 平衡括号提取 var player_aaaa={...}，避免 split('</script>') 在别的页面被截断
  var p = h.indexOf('var player_aaaa=');
  if (p < 0) return '';
  var st = h.indexOf('{', p);
  if (st < 0) return '';
  var dep = 0, ins = false, esc = false, en = -1;
  for (var j = st; j < h.length; j++){
    var ch = h.charAt(j);
    if (ins){
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') ins = false;
    } else {
      if (ch === '"') ins = true;
      else if (ch === '{') dep++;
      else if (ch === '}') { dep--; if (dep === 0) { en = j; break; } }
    }
  }
  if (en < 0) return '';

  var data;
  try { data = JSON.parse(h.substring(st, en + 1)); } catch(err2) { return ''; }
  var u = String(data.url || '');
  if (!u) return '';

  var enc = Number(data.encrypt || 0);
  if (enc === 2){
    try { u = decodeURIComponent(b64(u)); } catch(err3) { u = b64(u); }
  } else if (enc === 1){
    try { u = decodeURIComponent(u); } catch(err4) {}
  }
  return u.replace(/\\\//g, '/');
})()

